sys_variable_value.value:
(function execute(inputs, outputs) {
    var inputName = (inputs.company_name || "").toString().trim();
    if (!inputName) {
        outputs.top_10_json = "[]";
        return; 
    }

    try {
        var fuzzyHelper = new global.FindClosestCompany();
        outputs.top_10_json = fuzzyHelper.findCompanyByCode(inputName);
    } catch (e) {
        gs.error("Fuzzy Search failed in Flow Action: " + e.message);
        outputs.top_10_json = "[]";
    }

})(inputs, outputs);

